export interface TicketDrug {
  productId: string;
  quantity: number;
  price: number;
}

const toFiniteNumber = (value: unknown): number => {
  const parsed = typeof value === 'string' ? parseFloat(value) : value;

  return typeof parsed === 'number' && Number.isFinite(parsed) ? parsed : 0;
};

// Map shopping-cart line items to the `drugs` entries stored in the ticket valueAsJson.
export const buildTicketDrugs = (lineItems: unknown): TicketDrug[] => {
  if (!Array.isArray(lineItems)) {
    return [];
  }

  return lineItems.reduce<TicketDrug[]>((drugs, lineItem) => {
    const productId =
      typeof lineItem?.productId === 'string' ? lineItem.productId.trim() : '';
    const quantity = toFiniteNumber(lineItem?.quantity);

    if (!productId || quantity <= 0) {
      return drugs;
    }

    const existing = drugs.find((drug) => drug.productId === productId);

    if (existing) {
      // The cart stores one line per "add" tap, so repeated products are merged.
      existing.quantity += quantity;
      return drugs;
    }

    drugs.push({
      productId,
      quantity,
      price: toFiniteNumber(lineItem?.price),
    });
    return drugs;
  }, []);
};

import {buildTicketDrugs} from '../src/screens/doctor-detail-screen/ticket-drugs';

describe('buildTicketDrugs', () => {
  test('maps cart line items to ticket drugs', () => {
    expect(
      buildTicketDrugs([
        {productId: 'drug-1', quantity: 2, price: 239.2, isSelected: true},
      ]),
    ).toEqual([{productId: 'drug-1', quantity: 2, price: 239.2}]);
  });

  test('merges repeated lines of the same product', () => {
    expect(
      buildTicketDrugs([
        {productId: 'drug-1', quantity: 1, price: 1664},
        {productId: 'drug-1', quantity: 1, price: 1664},
      ]),
    ).toEqual([{productId: 'drug-1', quantity: 2, price: 1664}]);
  });

  test('parses a price returned as a string', () => {
    expect(
      buildTicketDrugs([{productId: 'drug-1', quantity: 1, price: '239.2'}]),
    ).toEqual([{productId: 'drug-1', quantity: 1, price: 239.2}]);
  });

  test('skips lines without a product id or a positive quantity', () => {
    expect(
      buildTicketDrugs([
        {quantity: 1, price: 10},
        {productId: 'drug-2', quantity: 0, price: 10},
      ]),
    ).toEqual([]);
  });

  test('returns an empty list when the cart has no line items', () => {
    expect(buildTicketDrugs(undefined)).toEqual([]);
  });
});

