const toFiniteNumber = (value: unknown): number => {
  const parsed = typeof value === 'string' ? Number.parseFloat(value) : value;

  return typeof parsed === 'number' && Number.isFinite(parsed) ? parsed : 0;
};

export interface CartSelectionItem {
  price?: unknown;
  quantity?: unknown;
  selected?: unknown;
}

export const isCartItemSelected = (item: CartSelectionItem): boolean =>
  item.selected === true && toFiniteNumber(item.quantity) > 0;

export const areAllCartItemsSelected = (
  items: readonly CartSelectionItem[],
): boolean => items.length > 0 && items.every((item) => item.selected === true);

export const countSelectedCartItems = (
  items: readonly CartSelectionItem[],
): number => items.filter((item) => isCartItemSelected(item)).length;

export const getSelectedCartTotal = (
  items: readonly CartSelectionItem[],
): number =>
  items.reduce((total, item) => {
    if (!isCartItemSelected(item)) {
      return total;
    }

    return total + toFiniteNumber(item.price) * toFiniteNumber(item.quantity);
  }, 0);

import {
  areAllCartItemsSelected,
  countSelectedCartItems,
  getSelectedCartTotal,
} from '../src/screens/shopping-cart-screen/shopping-cart-selection';

const cart = [
  {productId: 'xarelto', quantity: 1, price: 1664, selected: false},
  {productId: 'cozaar', quantity: 1, price: '239.2', selected: false},
];

describe('shopping cart selection', () => {
  test('counts and prices nothing while every item is unchecked', () => {
    expect(countSelectedCartItems(cart)).toBe(0);
    expect(getSelectedCartTotal(cart)).toBe(0);
    expect(areAllCartItemsSelected(cart)).toBe(false);
  });

  test('includes only the checked items in the count and total', () => {
    const selected = [{...cart[1], selected: true}];

    expect(countSelectedCartItems([...cart.slice(0, 1), ...selected])).toBe(1);
    expect(getSelectedCartTotal([...cart.slice(0, 1), ...selected])).toBe(239.2);
  });

  test('treats every item as selected only when all boxes are checked', () => {
    const selected = cart.map((item) => ({...item, selected: true}));

    expect(areAllCartItemsSelected(selected)).toBe(true);
    expect(countSelectedCartItems(selected)).toBe(2);
    expect(getSelectedCartTotal(selected)).toBe(1903.2);
  });

  test('ignores a checked item whose quantity is zero', () => {
    expect(
      countSelectedCartItems([{quantity: 0, price: 10, selected: true}]),
    ).toBe(0);
    expect(
      getSelectedCartTotal([{quantity: 0, price: 10, selected: true}]),
    ).toBe(0);
  });
});

